{
  "missing_information": [
    {
      "category": "system",
      "gap": "No information about which platform or channel childcare messages arrive through (e.g., email, a parent portal app, paper notices, messaging app)",
      "why_it_matters": "The communication channel determines whether automated ingestion or monitoring is technically feasible and what integration points are needed"
    },
    {
      "category": "decision",
      "gap": "No criteria defined for which messages require a response versus which are informational only",
      "why_it_matters": "Automating or routing responses requires a clear rule set distinguishing action-required notices from read-only announcements"
    },
    {
      "category": "output",
      "gap": "No description of where or how special events and items-to-bring are recorded after being identified",
      "why_it_matters": "Understanding the target storage (calendar, to-do list, shared note, etc.) is essential for designing an automated capture and reminder step"
    },
    {
      "category": "manual_effort",
      "gap": "Unknown how much time and cognitive effort is spent reading, triaging, and responding to messages per week",
      "why_it_matters": "Quantifying manual effort helps prioritize which sub-steps offer the highest automation return"
    },
    {
      "category": "frequency",
      "gap": "No information on how often messages arrive or how many require action in a typical week",
      "why_it_matters": "Message volume and cadence affect whether real-time automation or batch processing is more appropriate"
    },
    {
      "category": "exception",
      "gap": "No mention of what happens when a deadline for a response or a required item is missed or nearly missed",
      "why_it_matters": "Exception handling and escalation paths are critical for reliability and must be designed into any automated workflow"
    },
    {
      "category": "actor",
      "gap": "Unclear whether one parent or multiple caregivers are involved in reading and responding to messages",
      "why_it_matters": "Multiple actors require coordination logic (e.g., avoiding duplicate responses) and shared visibility into reminders"
    },
    {
      "category": "integration_constraint",
      "gap": "No information about whether the childcare provider's system supports any API, webhook, or structured data export",
      "why_it_matters": "Integration feasibility depends entirely on what the sending system exposes; without it, only email-scraping or manual entry may be possible"
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "Through which channel or platform do childcare messages arrive — for example, a dedicated parent portal, email, a messaging app, or physical paper notices?",
      "targets": ["system", "integration_constraint"]
    },
    {
      "id": "Q2",
      "question": "How do you currently decide whether a message needs a reply versus just needs to be read and noted — is there a consistent signal like a specific subject line, a form, or a deadline mentioned?",
      "targets": ["decision"]
    },
    {
      "id": "Q3",
      "question": "When you identify a special event or an item to bring, where do you record it so you and your household remember it — for instance, a phone calendar, a shared list app, or something else?",
      "targets": ["output"]
    },
    {
      "id": "Q4",
      "question": "Roughly how many childcare messages do you receive in a typical week, and of those, how many usually require you to take some action?",
      "targets": ["frequency", "manual_effort"]
    },
    {
      "id": "Q5",
      "question": "Is it just you who reads and responds to these messages, or do other caregivers also need to see and act on them?",
      "targets": ["actor"]
    },
    {
      "id": "Q6",
      "question": "What happens if a response deadline or a required item is missed — do you receive a follow-up from the childcare provider, or is there no safety net currently in place?",
      "targets": ["exception"]
    }
  ]
}
